#1 SELECT TOP 10 FirstName, LastName FROM Employees ORDER BY LastName;
#2 SELECT GETDATE() AS CurrentDateTime;
#3 SELECT ISNULL(FirstName, '') AS FirstName, ISNULL(LastName, '') AS LastName FROM Users;
#4 SELECT LEN(Description) AS DescLength FROM Products;
#5 SELECT CHARINDEX('@', Email) AS AtPosition FROM Contacts;
#6 SELECT UPPER(FirstName) AS UpperName, LOWER(LastName) AS LowerName FROM People;
#7 SELECT RTRIM(LTRIM(Code)) AS CleanCode FROM Items;
#8 SELECT ABS(Amount) AS AbsAmount, ROUND(Price, 2) AS RoundedPrice FROM Orders;
#9 SELECT CEILING(Tax) AS TaxCeiling, FLOOR(Discount) AS DiscountFloor FROM Invoices;
#10 SELECT GETUTCDATE() AS UtcNow;
#11 SELECT SCOPE_IDENTITY() AS LastId;
#12 SELECT @@IDENTITY AS LastIdentity;
#13 SELECT @@ROWCOUNT AS RowsAffected;
#14 SELECT DB_NAME() AS DatabaseName;
#15 SELECT HOST_NAME() AS HostName;
#16 SELECT NEWID() AS NewGuid;
#17 SELECT SUBSTRING(Description, 1, 50) AS ShortDesc FROM Products;
#18 SELECT LEFT(Code, 3) AS Prefix, RIGHT(Code, 2) AS Suffix FROM Parts;
#19 SELECT REPLACE(Title, 'Old', 'New') AS UpdatedTitle FROM Articles;
#20 SELECT REPLICATE('*', Rating) AS Stars FROM Reviews;
#21 SELECT REVERSE(Name) AS ReversedName FROM Categories;
#22 SELECT STUFF(Phone, 1, 3, '***') AS MaskedPhone FROM Contacts;
#23 SELECT SPACE(5) AS FiveSpaces;
#24 SELECT CAST(Price AS DECIMAL(10,2)) AS PriceDec FROM Products;
#25 SELECT CONVERT(VARCHAR(10), OrderDate, 101) AS OrderDateStr FROM Orders;
#26 SELECT TRY_CAST(Value AS INT) AS SafeInt FROM DataImport;
#27 SELECT TRY_CONVERT(DECIMAL(10,2), Amount) AS SafeAmount FROM Transactions;
#28 SELECT COALESCE(Phone, Mobile, Email, 'N/A') AS ContactInfo FROM Customers;
#29 SELECT NULLIF(Price, 0) AS PriceOrNull FROM Products;
#30 SELECT IIF(Status = 1, 'Active', 'Inactive') AS StatusText FROM Accounts;
#31 SELECT CHOOSE(Quarter, 'Q1', 'Q2', 'Q3', 'Q4') AS QuarterName FROM Sales;
#32 SELECT DATEADD(day, 30, OrderDate) AS DueDate FROM Orders;
#33 SELECT DATEDIFF(day, OrderDate, GETDATE()) AS DaysSince FROM Orders;
#34 SELECT DATEPART(year, OrderDate) AS OrderYear, DATEPART(month, OrderDate) AS OrderMonth FROM Orders;
#35 SELECT YEAR(OrderDate) AS OrderYear, MONTH(OrderDate) AS OrderMonth, DAY(OrderDate) AS OrderDay FROM Orders;
#36 SELECT EOMONTH(OrderDate) AS EndOfMonth FROM Orders;
#37 SELECT FORMAT(OrderDate, 'yyyy-MM-dd') AS FormattedDate FROM Orders;
#38 SELECT STRING_AGG(Name, ', ') AS AllNames FROM Employees;
#39 SELECT STRING_SPLIT('a,b,c', ',') AS Parts;
#40 SELECT ROW_NUMBER() OVER (ORDER BY Salary DESC) AS Rank, Name, Salary FROM Employees;
#41 SELECT RANK() OVER (ORDER BY Score DESC) AS Rank, Name, Score FROM Results;
#42 SELECT DENSE_RANK() OVER (ORDER BY Score DESC) AS Rank, Name, Score FROM Results;
#43 SELECT NTILE(4) OVER (ORDER BY Salary DESC) AS Quartile, Name, Salary FROM Employees;
#44 SELECT LEAD(Salary, 1) OVER (ORDER BY EmployeeId) AS NextSalary, Salary FROM Employees;
#45 SELECT LAG(Salary, 1) OVER (ORDER BY EmployeeId) AS PrevSalary, Salary FROM Employees;
#46 SELECT FIRST_VALUE(Name) OVER (ORDER BY Salary DESC) AS TopEarner FROM Employees;
#47 SELECT LAST_VALUE(Name) OVER (ORDER BY Salary DESC RANGE BETWEEN UNBOUNDED PRECEDING AND UNBOUNDED FOLLOWING) AS BottomEarner FROM Employees;
#48 SELECT PATINDEX('%[0-9]%', Address) AS FirstDigitPos FROM Customers;
#49 SELECT CAST(Price AS VARCHAR(20)) AS PriceStr FROM Products;
#50 SELECT PARSE('2024-01-15' AS DATE) AS ParsedDate;
#51 SELECT JSON_VALUE(JsonData, '$.name') AS Name FROM JsonStore;
#52 SELECT JSON_QUERY(JsonData, '$.address') AS Address FROM JsonStore;
#53 SELECT OPENJSON(JsonData) AS JsonRows FROM JsonStore;
#54 SELECT Name, Salary FROM Employees ORDER BY Salary DESC OFFSET 5 ROWS FETCH NEXT 10 ROWS ONLY;
#55 SELECT TOP 10 WITH TIES Name, Score FROM Results ORDER BY Score DESC;
#56 SELECT OBJECT_NAME(object_id) AS ObjectName FROM sys.objects;
#57 SELECT OBJECT_ID('Employees') AS ObjectId;
#58 SELECT COL_LENGTH('Employees', 'FirstName') AS ColLen;
#59 SELECT COL_NAME(OBJECT_ID('Employees'), 1) AS FirstCol;
#60 SELECT * FROM (SELECT Year, Amount FROM Sales) src PIVOT (SUM(Amount) FOR Year IN ([2023], [2024])) piv;
#61 SELECT * FROM (SELECT Department, Value FROM Data) src UNPIVOT (Value FOR Department IN ([Sales], [IT], [HR])) unpvt;
#62 SELECT FORMAT(GETDATE(), 'D', 'en-US') AS USDate;
#63 SELECT CAST(GETDATE() AS DATE) AS TodayDate;
#64 SELECT CAST(GETDATE() AS TIME) AS TodayTime;
#65 SELECT SUSER_SNAME() AS LoginName;
#66 SELECT ORIGINAL_LOGIN() AS OrigLogin;
#67 SELECT APP_NAME() AS AppName;
#68 SELECT HOST_ID() AS HostId;
#69 SELECT GETANSINULL() AS AnsNullSetting;
#70 SELECT COALESCE(NULLIF(Tax, 0), 0.08) AS EffectiveTax FROM Orders;
#71 SELECT LEFT(Name, 1) AS Initial, UPPER(LEFT(Name, 1)) AS UpperInitial FROM People;
#72 SELECT DATEADD(month, 3, HireDate) AS ReviewDate FROM Employees;
#73 SELECT DATEDIFF(year, HireDate, GETDATE()) AS YearsEmployed FROM Employees;
#74 SELECT DATEPART(quarter, OrderDate) AS Quarter, COUNT(*) AS OrderCount FROM Orders GROUP BY DATEPART(quarter, OrderDate);
#75 SELECT EOMONTH(GETDATE()) AS LastDayOfMonth;
#76 SELECT STRING_AGG(DISTINCT City, ', ') AS UniqueCities FROM Customers;
#77 SELECT CONVERT(VARCHAR(10), GETDATE(), 112) AS CompactDate;
#78 SELECT CONVERT(VARCHAR(10), GETDATE(), 103) AS BritishDate;
#79 SELECT CONVERT(VARCHAR(10), GETDATE(), 104) AS GermanDate;
#80 SELECT CHECKSUM(Name, Age, Salary) AS RowChecksum FROM Employees;
#81 SELECT CHECKSUM_AGG(BINARY_CHECKSUM(*)) AS TableChecksum FROM Employees;
#82 SELECT CASE WHEN Score >= 90 THEN 'A' WHEN Score >= 80 THEN 'B' ELSE 'C' END AS Grade FROM Results;
#83 SELECT NULLIF(TRIM(Code), '') AS CleanCode FROM Products;
#84 SELECT CAST(Amount AS DECIMAL(18,2)) * 1.1 AS AmountWithTax FROM Invoices;
#85 SELECT CONVERT(VARCHAR(20), Price) + ' USD' AS PriceDisplay FROM Products;
#86 SELECT STUFF((SELECT ', ' + Name FROM Cities FOR XML PATH('')), 1, 2, '') AS CityList;
#87 SELECT ROW_NUMBER() OVER (PARTITION BY DepartmentId ORDER BY Salary DESC) AS DeptRank, Name, Salary FROM Employees;
#88 SELECT Name, CAST(Salary AS DECIMAL(18,2)) AS Salary FROM Employees WHERE Salary > 50000;
#89 SELECT IIF(EXISTS (SELECT 1 FROM Orders WHERE CustomerId = c.Id), 'HasOrders', 'NoOrders') AS OrderStatus FROM Customers c;
#90 SELECT LEN(ISNULL(TRIM(Description), '')) AS CleanLen FROM Articles;
#91 SELECT DATEADD(hour, 2, StartTime) AS EndTime FROM Appointments;
#92 SELECT DATEDIFF(minute, StartTime, EndTime) AS DurationMinutes FROM Appointments;
#93 SELECT DATEPART(weekday, OrderDate) AS DayOfWeek FROM Orders;
#94 SELECT FORMAT(Price, 'C', 'en-US') AS CurrencyPrice FROM Products;
#95 SELECT CONVERT(DECIMAL(10,2), 123.4567) AS RoundedNum;
#96 SELECT BINARY_CHECKSUM(*) AS RowHash FROM Employees;
#97 SELECT COALESCE(CAST(NULLIF(Phone, '') AS VARCHAR(20)), 'No Phone') AS PhoneDisplay FROM Contacts;
#98 SELECT DATEADD(day, -7, GETDATE()) AS LastWeek;
#99 SELECT DATEDIFF(week, HireDate, GETDATE()) AS WeeksEmployed FROM Employees;
#100 SELECT GETDATE() AS Now, GETUTCDATE() AS UtcNow, SCOPE_IDENTITY() AS LastId, NEWID() AS Guid;
